// 9LMNTS Studio Canonical Lead Parser & Two-Layer Deposit Calculator (v2)
const item = $input.first().json || {};

const clientName = item.clientName || item.name || 'Prospect';
const businessName = item.businessName || item.company || item.clientId || 'Direct Prospect';
const clientEmail = item.email || item.clientEmail || 'N/A';
const phone = item.phone || item.mobile || 'N/A';
const source = item.source || item.sourceUrl || item.url || 'https://9lmntsstudio.com';
const pathType = item.path || 'agency';
const focusArea = item.focusArea || item.service || item.bottleneck || 'Custom Agency Website & Booking';
const rawPackage = String(item.package || item.service || item.bottleneck || 'Flow Sprint');
const lowerPkg = rawPackage.toLowerCase();
const paymentPreference = String(item.paymentPreference || 'interac').toLowerCase();
const manychatKeyword = item.manychat_keyword || 'DIRECT';
const roleRouter = item.role_router || 'N/A';
const utmSummary = [item.utm_source, item.utm_medium, item.utm_campaign, item.utm_content].filter(Boolean).join(' / ') || 'direct';
const extraMeta = [item.headcount ? `Guests: ${item.headcount}` : '', item.targetDate ? `Target: ${item.targetDate}` : ''].filter(Boolean).join(' | ');
const notes = [item.notes || 'Standard inquiry', extraMeta].filter(Boolean).join(' — ');

// Canonical Live Package & 50% Kickoff Deposit Mapping
let packageTier = 'Flow Sprint';
let totalQuote = 1500;
let depositDue = 750;
let turnaround = '5–7 Days';

if (lowerPkg.includes('barter') || lowerPkg.includes('free beta')) {
  packageTier = 'January Barter / Live SaaS Pilot';
  totalQuote = 0;
  depositDue = 0;
  turnaround = 'Pilot Lock';
} else if (lowerPkg.includes('custom')) {
  packageTier = 'Custom Scale';
  totalQuote = 0;
  depositDue = 0;
  turnaround = 'Scoped with Darnley';
} else if (lowerPkg.includes('spark') || lowerPkg.includes('500') || lowerPkg.includes('modular')) {
  packageTier = 'Spark Drop-In';
  totalQuote = 500;
  depositDue = 250;
  turnaround = '48 Hours';
} else if (lowerPkg.includes('cypher') || lowerPkg.includes('venue') || lowerPkg.includes('5000') || lowerPkg.includes('5,000') || lowerPkg.includes('enterprise')) {
  packageTier = 'Cypher OS';
  totalQuote = 5000;
  depositDue = 2500;
  turnaround = '2–3 Weeks';
} else if (lowerPkg.includes('beat') || lowerPkg.includes('3000') || lowerPkg.includes('3,000') || lowerPkg.includes('handyman') || lowerPkg.includes('reception') || lowerPkg.includes('title arena') || lowerPkg.includes('2,500')) {
  packageTier = 'Beat Sprint';
  totalQuote = 3000;
  depositDue = 1500;
  turnaround = '1–2 Weeks';
} else if (lowerPkg.includes('flow') || lowerPkg.includes('1500') || lowerPkg.includes('1,500') || lowerPkg.includes('catering') || lowerPkg.includes('recovery') || lowerPkg.includes('sponsor') || lowerPkg.includes('elite')) {
  packageTier = 'Flow Sprint';
  totalQuote = 1500;
  depositDue = 750;
  turnaround = '5–7 Days';
}

const paymentInstructions = paymentPreference === 'paypal'
  ? `PayPal Business Invoice requested from 9lmntstudio@gmail.com (50% Deposit: ${depositDue > 0 ? '$' + depositDue + ' CAD' : 'Scoped'}).`
  : `Interac e-Transfer to 9lmntstudio@gmail.com (Desjardins Autodeposit Active, 0% fee). 50% Kickoff Due: ${depositDue > 0 ? '$' + depositDue + ' CAD' : 'Scoped'}.`;

const quoteLabel = totalQuote > 0 ? `$${totalQuote.toLocaleString('en-CA')} CAD` : 'Custom / Pilot';
const depositLabel = depositDue > 0 ? `$${depositDue.toLocaleString('en-CA')} CAD` : 'Agreed Scope';

const formattedAlert = [
  '⚡ [NEW 9LMNTS SPRINT / CAMPAIGN LEAD]',
  `Client: ${clientName} (${businessName})`,
  `Email: ${clientEmail} | Phone: ${phone}`,
  `Path: ${pathType.toUpperCase()} | Focus: ${focusArea}`,
  `Package: ${packageTier} (${quoteLabel})`,
  `50% Kickoff Deposit: ${depositLabel} (${paymentPreference.toUpperCase()})`,
  `Turnaround: ${turnaround}`,
  `Trigger / Role: ${manychatKeyword} / ${roleRouter} | UTM: ${utmSummary}`,
  `Source: ${source}`,
  `Notes: ${notes}`
].join('\n');

return [{
  json: {
    clientName,
    businessName,
    clientEmail,
    phone,
    source,
    path: pathType,
    focusArea,
    rawPackage,
    packageTier,
    totalQuote,
    depositDue,
    quoteLabel,
    depositLabel,
    turnaround,
    paymentPreference,
    paymentInstructions,
    manychatKeyword,
    roleRouter,
    utmSummary,
    formattedAlert,
    notes,
    timestamp: item.submittedAt || item.timestamp || new Date().toISOString()
  }
}];

